export const REGIONS = Object.keys(LOCATIONS).sort();

export function getDistricts(region) {
  if (!region || !LOCATIONS[region]) return [];
  return Object.keys(LOCATIONS[region]).sort();
}

export function getWards(region, district) {
  if (!region || !district || !LOCATIONS[region]?.[district]) return [];
  return Object.keys(LOCATIONS[region][district]).sort();
}

export function getVillages(region, district, ward) {
  if (!region || !district || !ward) return [];
  const arr = LOCATIONS[region]?.[district]?.[ward];
  return arr ? arr.slice().sort() : [];
}

// Inatafuta Mkoa husika ukipewa jina la Wilaya (kwa ajili ya kujaza Region
// kiotomatiki wakati wa ku-Edit mwanafunzi aliyesajiliwa kabla ya hii feature).
export function findRegionForDistrict(district) {
  if (!district) return "";
  for (const region of Object.keys(LOCATIONS)) {
    if (LOCATIONS[region][district]) return region;
  }
  return "";
}
